135	        wraps the definition list instead of landing on it directly.
136	      */}
137	      <div aria-live="polite" role="status">
138	        <dl className="grid gap-1 font-mono text-muted-foreground text-sm/6">
139	          <div className="flex gap-3">
140	            <dt className="w-16 shrink-0 text-muted-foreground/60">{label}</dt>
141	            <dd className="min-w-0 flex-1">
142	              <StableSlot value={detail} variants={DETAIL_VARIANTS} />
143	            </dd>
144	          </div>
145	        </dl>
146	      </div>
147	      <div className="flex flex-wrap items-center gap-3">
148	        <MarketingButton
149	          aria-disabled={rebakeLocked}
150	          className={REBAKE_LOCKED_LOOK}
151	          onClick={handleRebake}
152	          variant="outline"
153	        >
154	          <StableSlot value={rebakeLabel} variants={REBAKE_LABELS} />
155	        </MarketingButton>
156	        {/*
157	          Rendered in every phase, hidden from sight and from the a11y tree
158	          when it doesn't apply, so the row always reserves its exact
159	          footprint. `invisible` also takes it out of the tab order.
160	        */}
